import 'package:flutter/material.dart';
import '../services/auth_service.dart';
class RegisterScreen extends StatefulWidget{const RegisterScreen({super.key});@override State<RegisterScreen> createState()=>_S();}
class _S extends State<RegisterScreen>{final e=TextEditingController(),p=TextEditingController(),confirm=TextEditingController();bool busy=false;String? error;
 Future<void> go()async{setState(()=>busy=true);try{if(e.text.trim().isEmpty||!e.text.contains('@'))throw Exception('Enter a valid email.');if(p.text.length<8)throw Exception('Password must be at least 8 characters.');if(p.text!=confirm.text)throw Exception('Passwords do not match.');await AuthService().signUp(e.text.trim(),p.text);if(!mounted)return;if(AuthService().user!=null)Navigator.pushReplacementNamed(context,'/onboarding');else ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Account created. Check your email to confirm the account, then sign in.')));}catch(x){if(mounted)setState(()=>error=x.toString().replaceFirst('Exception: ','').replaceFirst('AuthException(message: ','').replaceAll(')', ''));}finally{if(mounted)setState(()=>busy=false);}}
 Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create account')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Join AFRICA LINK',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:16),TextField(controller:e,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Password')),TextField(controller:confirm,obscureText:true,decoration:const InputDecoration(labelText:'Confirm password')),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))),const SizedBox(height:16),FilledButton(onPressed:busy?null:go,child:Text(busy?'Creating…':'Create account'))]));}
